CREATE TABLE `tb_returns` (
  `ID` bigint unsigned NOT NULL AUTO_INCREMENT,
  `buyer_order_ID` int unsigned NOT NULL,
  `user_ID` int NOT NULL,
  `reason` varchar(500) NOT NULL,
  `return_status` enum('Requested','Approved','Rejected','Completed') NOT NULL DEFAULT 'Requested',
  `status` bit(1) NOT NULL DEFAULT b'1',
  `creation_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `last_update` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`ID`),
  KEY `fk_return_order` (`buyer_order_ID`),
  KEY `fk_return_user` (`user_ID`),
  CONSTRAINT `fk_return_order` FOREIGN KEY (`buyer_order_ID`) REFERENCES `tb_buyer_orders` (`ID`),
  CONSTRAINT `fk_return_user` FOREIGN KEY (`user_ID`) REFERENCES `tb_users` (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
