CREATE DEFINER=`angeleutiquio.cruz`@`%` PROCEDURE `sp_generate_products`(IN p_total INT)
BEGIN

    DECLARE v_i INT DEFAULT 1;

    WHILE v_i <= p_total DO

        INSERT INTO tb_products
        (
            SKU,
            name,
            description,
            current_price,
            current_stock,
            status
        )
        VALUES
        (
            CONCAT('SKU-', FLOOR(100000 + RAND()*900000)),

            ELT(
                FLOOR(1 + RAND()*10),
                'Laptop Gamer',
                'Mouse Inalambrico',
                'Teclado Mecanico',
                'Monitor Full HD',
                'Audifonos Bluetooth',
                'Smartphone',
                'Tablet Android',
                'Disco SSD',
                'Memoria USB',
                'Camara Web'
            ),

            CONCAT(
                'Producto de catalogo generado automaticamente #',
                v_i
            ),

            ROUND(100 + RAND()*15000,2),

            FLOOR(1 + RAND()*500),

            1
        );

        SET v_i = v_i + 1;

    END WHILE;

END ;;
