DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_insert_generated_user`(
    IN p_gender VARCHAR(20),
    IN p_country CHAR(2),
    IN p_age INT,
    IN p_status BIT(1)
)
BEGIN
    DECLARE v_first_name VARCHAR(50);
    DECLARE v_last_name VARCHAR(50);
    DECLARE v_domain VARCHAR(30);
    DECLARE v_email VARCHAR(100);
    DECLARE v_nick VARCHAR(50);
    DECLARE v_suffix INT;
    DECLARE v_user_id INT;
    DECLARE v_birth_date DATE;
    DECLARE v_email_exists INT DEFAULT 0;
    DECLARE v_nick_exists INT DEFAULT 0;

    CALL sp_random_first_name(p_gender, v_first_name);
    CALL sp_random_last_name(v_last_name);
    CALL sp_random_email_domain(v_domain);

    -- La fecha se calcula para que TIMESTAMPDIFF reporte exactamente
    -- la edad seleccionada en la fecha de ejecución.
    SET v_birth_date = DATE_SUB(CURDATE(), INTERVAL p_age YEAR);

    -- Se generan direcciones y nicknames con sufijos numéricos.
    -- El ciclo comprueba ambos valores antes de insertar.
    REPEAT
        SET v_suffix = FLOOR(100 + RAND() * 999900);

        SET v_email = CONCAT(
            LOWER(v_first_name), '.', LOWER(v_last_name),
            v_suffix, '@', v_domain
        );

        SET v_nick = CONCAT(
            LOWER(LEFT(v_first_name, 1)),
            LOWER(v_last_name),
            v_suffix
        );

        SELECT COUNT(*) INTO v_email_exists
        FROM tb_users
        WHERE email = v_email;

        SELECT COUNT(*) INTO v_nick_exists
        FROM tb_users
        WHERE nick = v_nick;
    UNTIL v_email_exists = 0 AND v_nick_exists = 0
    END REPEAT;

    INSERT INTO tb_users (email, nick, password)
    VALUES (v_email, v_nick, SHA2('123456', 256));

    SET v_user_id = LAST_INSERT_ID();

    INSERT INTO tb_people (
        user_ID,
        given_names,
        family_names,
        birth_date,
        gender,
        country_code,
        phone,
        status
    )
    VALUES (
        v_user_id,
        v_first_name,
        v_last_name,
        v_birth_date,
        p_gender,
        p_country,
        CONCAT(
            FLOOR(1000000000 + RAND() * 8999999999)
        ),
        p_status
    );
END ;;
DELIMITER ;
