CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_random_age`(
    IN p_min_age INT,
    IN p_max_age INT,
    OUT p_age INT
)
BEGIN
    IF p_min_age IS NULL OR p_max_age IS NULL OR
       p_min_age < 0 OR p_max_age < p_min_age THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Rango de edades no válido';
    END IF;

    SET p_age = p_min_age + FLOOR(RAND() * (p_max_age - p_min_age + 1));
END ;;
DELIMITER ;
