DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_register_new_user`(
    IN p_email          VARCHAR(100),
    IN p_nick           VARCHAR(50),
    IN p_password       VARCHAR(100),
    IN p_courtesy_title VARCHAR(20),
    IN p_given_names    VARCHAR(150),
    IN p_family_names   VARCHAR(150),
    IN p_birth_date     DATE,
    IN p_gender         VARCHAR(30),
    IN p_country_code   CHAR(2),
    IN p_phone          VARCHAR(25)
)
    MODIFIES SQL DATA
BEGIN
    DECLARE v_db_user   VARCHAR(100);
    DECLARE v_host      VARCHAR(255);
    DECLARE v_has_role  INT DEFAULT 0;
    DECLARE v_count     INT DEFAULT 0;
    DECLARE v_user_id   INT;
    DECLARE v_person_id BIGINT UNSIGNED;

    
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    
    DECLARE EXIT HANDLER FOR 1062
    BEGIN
        ROLLBACK;
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'El correo, el nick u otro dato �nico ya est� registrado';
    END;

    
    SET v_db_user = SUBSTRING_INDEX(USER(), '@', 1);
    SET v_host = SUBSTRING_INDEX(USER(), '@', -1);

    
    SELECT COUNT(*)
      INTO v_has_role
    FROM mysql.role_edges AS re
    WHERE re.TO_USER = v_db_user
      AND re.TO_HOST IN ('%', v_host)
      AND re.FROM_USER IN (
          'superadmin',
          'admin',
          'support',
          'user_not_registered'
      );

    IF v_has_role = 0 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'Acceso denegado: el usuario no tiene un rol autorizado';
    END IF;

    
    SET p_email = LOWER(TRIM(p_email));
    SET p_nick = TRIM(p_nick);
    SET p_password = TRIM(p_password);
    SET p_courtesy_title =
        NULLIF(TRIM(p_courtesy_title), '');
    SET p_given_names = TRIM(p_given_names);
    SET p_family_names =
        NULLIF(TRIM(p_family_names), '');
    SET p_gender =
        COALESCE(
            NULLIF(TRIM(p_gender), ''),
            'Prefiero no decirlo'
        );
    SET p_country_code =
        NULLIF(UPPER(TRIM(p_country_code)), '');
    SET p_phone = NULLIF(TRIM(p_phone), '');

    
    IF p_email IS NULL
       OR p_email NOT REGEXP
          '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$' THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El correo electr�nico es inv�lido';
    END IF;

    
    IF p_nick IS NULL OR CHAR_LENGTH(p_nick) < 3 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'El nick debe tener al menos 3 caracteres';
    END IF;

    
    IF p_password IS NULL OR CHAR_LENGTH(p_password) < 8 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'La contrase�a debe tener al menos 8 caracteres';
    END IF;

    
    IF p_given_names IS NULL OR p_given_names = '' THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El nombre es obligatorio';
    END IF;

    
    IF p_birth_date IS NOT NULL
       AND (
           p_birth_date > CURRENT_DATE
           OR p_birth_date < '1900-01-01'
       ) THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'La fecha de nacimiento es inv�lida';
    END IF;

    
    IF p_gender NOT IN (
        'Hombre',
        'Mujer',
        'Prefiero no decirlo'
    ) THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El g�nero indicado no es v�lido';
    END IF;

    
    IF p_country_code IS NOT NULL
       AND p_country_code NOT REGEXP '^[A-Z]{2}$' THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'El c�digo de pa�s debe contener 2 letras';
    END IF;

    
    IF p_phone IS NOT NULL
       AND p_phone NOT REGEXP '^[0-9+() -]{7,25}$' THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El tel�fono es inv�lido';
    END IF;

    
    SELECT COUNT(*)
      INTO v_count
    FROM tb_users
    WHERE email = p_email;

    IF v_count > 0 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'El correo electr�nico ya se encuentra registrado';
    END IF;

    
    SELECT COUNT(*)
      INTO v_count
    FROM tb_users
    WHERE nick = p_nick;

    IF v_count > 0 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El nick ya se encuentra en uso';
    END IF;

    
    START TRANSACTION;

    INSERT INTO tb_users (
        email,
        nick,
        password
    )
    VALUES (
        p_email,
        p_nick,
        MD5(p_password)
    );

    SET v_user_id = LAST_INSERT_ID();

    INSERT INTO tb_people (
        user_ID,
        courtesy_title,
        given_names,
        family_names,
        birth_date,
        gender,
        country_code,
        phone
    )
    VALUES (
        v_user_id,
        p_courtesy_title,
        p_given_names,
        p_family_names,
        p_birth_date,
        p_gender,
        p_country_code,
        p_phone
    );

    SET v_person_id = LAST_INSERT_ID();

    COMMIT;

    
    SELECT
        'Usuario y persona registrados correctamente' AS mensaje,
        v_user_id AS user_id,
        v_person_id AS person_id,
        p_email AS email,
        p_nick AS nick,
        v_db_user AS ejecutado_por,
        CURRENT_TIMESTAMP AS fecha_operacion;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
